DROP TABLE IF EXISTS exchanges;

CREATE TABLE exchanges (
    code VARCHAR(4) NOT NULL,
    name VARCHAR(255) NOT NULL,
    mic CHAR(4) NOT NULL,
    country_code CHAR(2) NOT NULL,
    timezone VARCHAR(64) NOT NULL,
    weekend_day_1 SMALLINT NOT NULL,
    weekend_day_2 SMALLINT NOT NULL,
    regular_open VARCHAR(5) NOT NULL,
    regular_close VARCHAR(5) NOT NULL,
    generation_start DATE NOT NULL,
    generation_end DATE NOT NULL,
    PRIMARY KEY (code),
    UNIQUE (mic),
    CONSTRAINT chk_exchanges_code_length CHECK (LENGTH(code) BETWEEN 4 AND 4),
    CONSTRAINT chk_exchanges_mic_length CHECK (LENGTH(mic) BETWEEN 4 AND 4),
    CONSTRAINT chk_exchanges_country_code_length CHECK (LENGTH(country_code) BETWEEN 2 AND 2),
    CONSTRAINT chk_exchanges_weekend_day_1_range CHECK (weekend_day_1 BETWEEN 0 AND 6),
    CONSTRAINT chk_exchanges_weekend_day_2_range CHECK (weekend_day_2 BETWEEN 0 AND 6),
    CONSTRAINT chk_exchanges_regular_open_time CHECK (LENGTH(regular_open)=5 AND SUBSTR(regular_open,3,1)=':' AND SUBSTR(regular_open,1,2) BETWEEN '00' AND '23' AND SUBSTR(regular_open,4,2) BETWEEN '00' AND '59'),
    CONSTRAINT chk_exchanges_regular_close_time CHECK (LENGTH(regular_close)=5 AND SUBSTR(regular_close,3,1)=':' AND SUBSTR(regular_close,1,2) BETWEEN '00' AND '23' AND SUBSTR(regular_close,4,2) BETWEEN '00' AND '59')
);

CREATE TABLE sessions (
    exchange_code VARCHAR(4) NOT NULL,
    type VARCHAR(16) NOT NULL,
    seq SMALLINT NOT NULL,
    open VARCHAR(5),
    close VARCHAR(5),
    at VARCHAR(5),
    PRIMARY KEY (exchange_code, type, seq),
    CONSTRAINT fk_sessions_exchange FOREIGN KEY (exchange_code) REFERENCES exchanges (code) ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT chk_sessions_type CHECK (type IN ('regular','pre_market','post_market','lunch_break','auction','halt')),
    CONSTRAINT chk_sessions_seq_range CHECK (seq >= 1),
    CONSTRAINT chk_sessions_open_time CHECK (LENGTH(open)=5 AND SUBSTR(open,3,1)=':' AND SUBSTR(open,1,2) BETWEEN '00' AND '23' AND SUBSTR(open,4,2) BETWEEN '00' AND '59'),
    CONSTRAINT chk_sessions_close_time CHECK (LENGTH(close)=5 AND SUBSTR(close,3,1)=':' AND SUBSTR(close,1,2) BETWEEN '00' AND '23' AND SUBSTR(close,4,2) BETWEEN '00' AND '59'),
    CONSTRAINT chk_sessions_at_time CHECK (LENGTH(at)=5 AND SUBSTR(at,3,1)=':' AND SUBSTR(at,1,2) BETWEEN '00' AND '23' AND SUBSTR(at,4,2) BETWEEN '00' AND '59')
);

CREATE TABLE holidays (
    exchange_code VARCHAR(4) NOT NULL,
    date DATE NOT NULL,
    name VARCHAR(255) NOT NULL,
    status VARCHAR(16) NOT NULL,
    origin VARCHAR(16) NOT NULL,
    seq SMALLINT NOT NULL,
    early_close_time VARCHAR(5),
    delayed_open_time VARCHAR(5),
    predicted SMALLINT,
    weekend_exception SMALLINT,
    source_url VARCHAR(2048),
    PRIMARY KEY (exchange_code, date, origin, seq),
    CONSTRAINT fk_holidays_exchange FOREIGN KEY (exchange_code) REFERENCES exchanges (code) ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT chk_holidays_status CHECK (status IN ('closed','early_close','delayed_open','special_session')),
    CONSTRAINT chk_holidays_origin CHECK (origin IN ('explicit','generated')),
    CONSTRAINT chk_holidays_seq_range CHECK (seq >= 1),
    CONSTRAINT chk_holidays_early_close_time_time CHECK (LENGTH(early_close_time)=5 AND SUBSTR(early_close_time,3,1)=':' AND SUBSTR(early_close_time,1,2) BETWEEN '00' AND '23' AND SUBSTR(early_close_time,4,2) BETWEEN '00' AND '59'),
    CONSTRAINT chk_holidays_delayed_open_time_time CHECK (LENGTH(delayed_open_time)=5 AND SUBSTR(delayed_open_time,3,1)=':' AND SUBSTR(delayed_open_time,1,2) BETWEEN '00' AND '23' AND SUBSTR(delayed_open_time,4,2) BETWEEN '00' AND '59'),
    CONSTRAINT chk_holidays_predicted CHECK (predicted IN (0, 1)),
    CONSTRAINT chk_holidays_weekend_exception CHECK (weekend_exception IN (0, 1))
);

CREATE TABLE ad_hoc_closures (
    exchange_code VARCHAR(4) NOT NULL,
    date DATE NOT NULL,
    seq SMALLINT NOT NULL,
    name VARCHAR(255) NOT NULL,
    status VARCHAR(16) NOT NULL,
    early_close_time VARCHAR(5),
    source_url VARCHAR(2048) NOT NULL,
    PRIMARY KEY (exchange_code, date, seq),
    CONSTRAINT fk_ad_hoc_closures_exchange FOREIGN KEY (exchange_code) REFERENCES exchanges (code) ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT chk_ad_hoc_closures_seq_range CHECK (seq >= 1),
    CONSTRAINT chk_ad_hoc_closures_status CHECK (status IN ('closed','early_close')),
    CONSTRAINT chk_ad_hoc_closures_early_close_time_time CHECK (LENGTH(early_close_time)=5 AND SUBSTR(early_close_time,3,1)=':' AND SUBSTR(early_close_time,1,2) BETWEEN '00' AND '23' AND SUBSTR(early_close_time,4,2) BETWEEN '00' AND '59')
);

CREATE TABLE confidence (
    exchange_code VARCHAR(4) NOT NULL,
    year SMALLINT NOT NULL,
    level VARCHAR(8) NOT NULL,
    source VARCHAR(32) NOT NULL,
    last_verified DATE,
    note VARCHAR(4096),
    PRIMARY KEY (exchange_code, year),
    CONSTRAINT fk_confidence_exchange FOREIGN KEY (exchange_code) REFERENCES exchanges (code) ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT chk_confidence_level CHECK (level IN ('high','medium','low')),
    CONSTRAINT chk_confidence_source CHECK (source IN ('fetcher','manual','predicted'))
);

